colors=[2,3,1,8,7]
g=[[0]*W for _ in range(H)]
for i,col in enumerate(colors):
    for dr,dc in mask:
        g[3*i+dr][3+dc]=col
# Preserve palette key in lower-right, except the overlaid last-copy cell.
for r in range(14,17):
    for j,col in enumerate(colors):
        c=8+j
        if (r,c)!=(14,8): g[r][c]=col
assert len(g)==18 and all(len(row)==15 for row in g)
